# region imports
from AlgorithmImports import *
from collections import deque
# endregion


# ---------------------------------------------------------------------------
# Parameters
# ---------------------------------------------------------------------------
SPY_SMA_PERIOD = 20                 # period of "its simple moving average" (Strategy A)
AAPL_RSI_PERIOD = 14                # "14-day RSI" (Strategy B)
AAPL_RED_DAY_COUNT = 3              # "red for 3 consecutive days"
STRATEGY_A_PORTFOLIO_PCT = 0.40     # "invest 40% of total portfolio value"
STRATEGY_B_CASH_PER_TRADE = 20000.0 # "buy $20,000 ... if at least $20,000 cash is available"

MIN_BARS_REQUIRED = AAPL_RED_DAY_COUNT + 1          # 3 red days needs 4 closes
HISTORY_SIZE = max(MIN_BARS_REQUIRED, SPY_SMA_PERIOD + 2)
WARM_UP_BARS = max(SPY_SMA_PERIOD + 2, AAPL_RSI_PERIOD + 2, MIN_BARS_REQUIRED) + 5

TERMINAL_ORDER_STATES = (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID)


# ---------------------------------------------------------------------------
# Market state (always updated from data, never gated)
# ---------------------------------------------------------------------------
class SymbolWindow:
    """Rolling daily close history for one symbol. Index 0 == most recent bar."""

    def __init__(self, size):
        self._closes = deque(maxlen=size)

    def update(self, bar):
        self._closes.appendleft(bar.close)

    @property
    def count(self):
        return len(self._closes)

    def close(self, index=0):
        return self._closes[index]

    def red_streak(self):
        """Consecutive days whose close is strictly below the previous close,
        counted backwards from the most recent bar."""
        streak = 0
        for i in range(len(self._closes) - 1):
            if self._closes[i] < self._closes[i + 1]:
                streak += 1
            else:
                break
        return streak


def crossed_above(x_today, x_yesterday, y_today, y_yesterday):
    """Yesterday X <= Y and today X > Y."""
    return x_yesterday <= y_yesterday and x_today > y_today


def crossed_below(x_today, x_yesterday, y_today, y_yesterday):
    """Mirror image of crossed_above."""
    return x_yesterday >= y_yesterday and x_today < y_today


# ---------------------------------------------------------------------------
# Strategy (a slot owning its own private lot)
# ---------------------------------------------------------------------------
class Strategy:
    """Base slot: owns a private lot, sells only shares it bought, and only
    evaluates its buy reason while flat / its sell reason while long."""

    def __init__(self, algorithm, name, symbol):
        self.algorithm = algorithm
        self.name = name
        self.symbol = symbol
        self.shares = 0
        self._ticket = None
        self._applied_fill = 0

    # -- lot bookkeeping ---------------------------------------------------
    @property
    def is_open(self):
        return self.shares > 0

    @property
    def is_busy(self):
        return self._ticket is not None

    def sync(self):
        """Fold fills of the in-flight order into this strategy's lot."""
        ticket = self._ticket
        if ticket is None:
            return
        filled = int(ticket.quantity_filled)
        if filled != self._applied_fill:
            self.shares += filled - self._applied_fill
            self._applied_fill = filled
        if self.shares < 0:
            self.shares = 0
        if ticket.status in TERMINAL_ORDER_STATES:
            self._ticket = None
            self._applied_fill = 0

    def _submit(self, quantity, tag):
        quantity = int(quantity)
        if quantity == 0:
            return
        ticket = self.algorithm.market_order(self.symbol, quantity, tag=tag)
        if ticket is None or ticket.status in (OrderStatus.INVALID, OrderStatus.CANCELED):
            return
        self._ticket = ticket
        self._applied_fill = 0
        self.sync()

    def buy_shares(self, quantity, tag):
        if quantity > 0:
            self._submit(quantity, tag)

    def sell_shares(self, quantity, tag):
        quantity = min(int(quantity), self.shares)
        if quantity > 0:
            self._submit(-quantity, tag)

    def liquidate_lot(self, tag):
        self.sell_shares(self.shares, tag)

    # -- rule hooks --------------------------------------------------------
    def buy_reason(self):
        raise NotImplementedError

    def buy_details(self):
        raise NotImplementedError

    def sell_reason(self):
        raise NotImplementedError

    def sell_details(self):
        raise NotImplementedError

    # -- evaluation --------------------------------------------------------
    def evaluate_sell(self):
        if self.is_busy or not self.is_open:
            return
        if self.sell_reason():
            self.sell_details()

    def evaluate_buy(self):
        if self.is_busy or self.is_open:
            return
        if self.buy_reason():
            self.buy_details()


class StrategyA(Strategy):
    """Slot 1 - SPY close / simple moving average crossovers."""

    def __init__(self, algorithm):
        super().__init__(algorithm, "Strategy A", algorithm.spy)

    def _values(self):
        window = self.algorithm.windows[self.symbol]
        sma_history = self.algorithm.spy_sma_history
        if window.count < 2 or len(sma_history) < 2:
            return None
        return window.close(0), window.close(1), sma_history[0], sma_history[1]

    def buy_reason(self):
        values = self._values()
        if values is None:
            return False
        return crossed_above(*values)

    def buy_details(self):
        # Invest 40% of total portfolio value in SPY.
        price = self.algorithm.windows[self.symbol].close(0)
        if price <= 0:
            return
        target_value = STRATEGY_A_PORTFOLIO_PCT * self.algorithm.portfolio.total_portfolio_value
        self.buy_shares(int(target_value / price), "Strategy A: close crossed above SMA")

    def sell_reason(self):
        values = self._values()
        if values is None:
            return False
        return crossed_below(*values)

    def sell_details(self):
        self.liquidate_lot("Strategy A: close crossed below SMA")


class StrategyB(Strategy):
    """Slot 2 - AAPL red-day streak entry, RSI(14) exit."""

    def __init__(self, algorithm):
        super().__init__(algorithm, "Strategy B", algorithm.aapl)

    def buy_reason(self):
        window = self.algorithm.windows[self.symbol]
        if window.count < MIN_BARS_REQUIRED:
            return False
        return window.red_streak() >= AAPL_RED_DAY_COUNT

    def buy_details(self):
        # Buy $20,000 of AAPL only if at least $20,000 cash is available.
        if self.algorithm.portfolio.cash < STRATEGY_B_CASH_PER_TRADE:
            return
        price = self.algorithm.windows[self.symbol].close(0)
        if price <= 0:
            return
        self.buy_shares(int(STRATEGY_B_CASH_PER_TRADE / price),
                        "Strategy B: 3 consecutive red days")

    def sell_reason(self):
        rsi = self.algorithm.aapl_rsi
        return rsi.is_ready and rsi.current.value > 60

    def sell_details(self):
        self.liquidate_lot("Strategy B: RSI(14) closed above 60")


# ---------------------------------------------------------------------------
# Template: no gate, slots run independently in parallel
# ---------------------------------------------------------------------------
class ParallelTemplate:

    def __init__(self, name, slots):
        self.name = name
        self.slots = slots

    def on_bar(self):
        for slot in self.slots:
            slot.sync()
        # Sells are evaluated before buys on any bar.
        for slot in self.slots:
            slot.evaluate_sell()
        for slot in self.slots:
            slot.evaluate_buy()


# ---------------------------------------------------------------------------
# Algorithm
# ---------------------------------------------------------------------------
class ParallelTwoSlotTemplateAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.tracked_symbols = []
        self.windows = {}
        for ticker in tickers:
            equity = self.add_equity(ticker, Resolution.DAILY)
            equity.set_data_normalization_mode(DataNormalizationMode.ADJUSTED)
            self.tracked_symbols.append(equity.symbol)
            self.windows[equity.symbol] = SymbolWindow(HISTORY_SIZE)

        self.spy = self.tracked_symbols[0]
        self.aapl = self.tracked_symbols[1]

        self.spy_sma = self.sma(self.spy, SPY_SMA_PERIOD, Resolution.DAILY)
        self.spy_sma_history = deque(maxlen=2)   # index 0 == today, 1 == yesterday
        self.aapl_rsi = self.rsi(self.aapl, AAPL_RSI_PERIOD,
                                 MovingAverageType.WILDERS, Resolution.DAILY)

        self.template = ParallelTemplate("Root", [StrategyA(self), StrategyB(self)])

        self.set_warm_up(WARM_UP_BARS, Resolution.DAILY)

    def on_data(self, slice):
        bars = {}
        for symbol in self.tracked_symbols:
            if slice.bars.contains_key(symbol):
                bar = slice.bars[symbol]
                if bar is not None and bar.close > 0:
                    bars[symbol] = bar

        # Market state is computed from data continuously, per symbol.
        for symbol, bar in bars.items():
            self.windows[symbol].update(bar)
        if self.spy in bars and self.spy_sma.is_ready:
            self.spy_sma_history.appendleft(self.spy_sma.current.value)

        if self.is_warming_up:
            return

        # Today's bar missing for any subscribed ticker -> skip all rules today.
        if len(bars) != len(self.tracked_symbols):
            return

        if not self._rules_are_formed():
            return

        self.template.on_bar()

    def _rules_are_formed(self):
        if not self.spy_sma.is_ready or len(self.spy_sma_history) < 2:
            return False
        if not self.aapl_rsi.is_ready:
            return False
        for symbol in self.tracked_symbols:
            if self.windows[symbol].count < MIN_BARS_REQUIRED:
                return False
        return True

