    # ---------------------------------------------------------------------------
    def strategy_a_sell(self):
        if not self.lot_a.can_sell:
            return
        if self.trackers[self.spy].close_crossed_below_sma:
            self.submit(self.lot_a, -self.lot_a.shares, "A sell: close crossed below SMA")

    def strategy_a_buy(self):
        if not self.lot_a.can_buy:
            return
        tracker = self.trackers[self.spy]
        if not tracker.close_crossed_above_sma:
            return
        price = tracker.close
        if price <= 0:
            return
        target_value = STRATEGY_A_ALLOCATION * float(self.portfolio.total_portfolio_value)
        quantity = int(target_value / price)
        if quantity > 0:
            self.submit(self.lot_a, quantity, "A buy: close crossed above SMA (40% of TPV)")

    # ---------------------------------------------------------------------------
    # Slot 2 - Strategy B (AAPL)
    # ---------------------------------------------------------------------------
    def strategy_b_sell(self):
        if not self.lot_b.can_sell:
            return
        rsi = self.trackers[self.aapl].rsi_value
        if rsi is not None and rsi > RSI_EXIT_LEVEL:
            self.submit(self.lot_b, -self.lot_b.shares, "B sell: RSI(14) closed above 60")

    def strategy_b_buy(self):
        if not self.lot_b.can_buy:
            return
        tracker = self.trackers[self.aapl]
        if not tracker.red_for(RED_DAYS_REQUIRED):
            return
        # "buy $20,000 if available": otherwise do nothing at all this bar
        if self.available_cash() < STRATEGY_B_CASH:
            return
        price = tracker.close
        if price <= 0:
            return
        quantity = int(STRATEGY_B_CASH / price)
        if quantity > 0:
            self.submit(self.lot_b, quantity, "B buy: 3 consecutive red days ($20,000)")

    # ---------------------------------------------------------------------------
    # Order plumbing (keeps each lot's share count private and exact)
    # ---------------------------------------------------------------------------
    def available_cash(self):
        """Cash on hand less cash already committed by unfilled buy orders."""
        cash = float(self.portfolio.cash)
        for order in self.transactions.get_open_orders():
            if order.quantity > 0:
                price = float(self.securities[order.symbol].price)
                cash -= float(order.quantity) * price
        return cash

    def submit(self, lot, quantity, reason):
        quantity = int(quantity)
        if quantity == 0:
            return
        ticket = self.market_order(lot.symbol, quantity, tag="{0} | {1}".format(lot.name, reason))
        if ticket is None:
            return
        status = ticket.status
        if status == OrderStatus.INVALID:
            return
        self.open_orders[ticket.order_id] = (lot, quantity)
        lot.pending += quantity

    def on_order_event(self, order_event):
        entry = self.open_orders.get(order_event.order_id)
        if entry is None:
            return
        lot, ordered_quantity = entry

        if order_event.fill_quantity != 0:
            lot.shares += int(order_event.fill_quantity)
            if lot.shares < 0:
                lot.shares = 0

        if order_event.status in (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID):
            lot.pending -= ordered_quantity
            del self.open_orders[order_event.order_id]

    def on_end_of_algorithm(self):
        self.log("Final lots -> {0}: {1} sh {2} | {3}: {4} sh {5}".format(
            self.lot_a.name, self.lot_a.shares, self.lot_a.symbol.value,
