#   One template, 2 slots, NO gate -> both slots run independently, in parallel.
#     Slot 1 - Strategy A (SPY): buy on close crossing above its moving average,
#              invest 40% of total portfolio value; sell on close crossing below
#              the moving average, liquidating Strategy A's entire private lot.
#     Slot 2 - Strategy B (AAPL): buy after 3 consecutive red days, $20,000 of AAPL
#              if at least $20,000 cash is available (otherwise do nothing this bar);
#              sell when the 14-day RSI closes above 60, liquidating the entire lot.
#
#   Every rule is evaluated once per daily bar, after the close. If ANY subscribed
#   ticker is missing today's bar, ALL rule evaluation is skipped for that day.
#   Market state (streaks, indicators) is always updated from whatever data arrives.
# ----------------------------------------------------------------------------------

TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

SMA_PERIOD = 50                 # length of "its moving average" for Strategy A
RSI_PERIOD = 14                 # Strategy B RSI length
RSI_EXIT_LEVEL = 60.0           # Strategy B sells while RSI closes above this level
RED_DAYS_REQUIRED = 3           # Strategy B buys on 3+ consecutive red days
STRATEGY_A_ALLOCATION = 0.40    # 40% of total portfolio value
STRATEGY_B_CASH = 20000.0       # dollar amount Strategy B tries to deploy


class SymbolTracker(object):
    """Continuously maintained market state for one ticker (never paused by rules)."""

    def __init__(self, symbol):
        self.symbol = symbol
        self.sma = SimpleMovingAverage(SMA_PERIOD)
        self.rsi = RelativeStrengthIndex(RSI_PERIOD, MovingAverageType.WILDERS)

        self.bars_seen = 0
        self.close = None
        self.previous_close = None
        self.open = None

        self.sma_value = None
        self.sma_ready = False
        self.previous_sma_value = None
        self.previous_sma_ready = False

        self.red_streak = 0
        self.green_streak = 0

    def update(self, bar):
        # today's values become yesterday's values before absorbing the new bar
        self.previous_close = self.close
        self.previous_sma_value = self.sma_value
        self.previous_sma_ready = self.sma_ready

        close = float(bar.close)
        self.open = float(bar.open)

        self.sma.update(bar.end_time, close)
        self.rsi.update(bar.end_time, close)

        # "red day" = close strictly below the previous close; "green" = strictly above
        if self.previous_close is not None:
            if close < self.previous_close:
                self.red_streak += 1
                self.green_streak = 0
            elif close > self.previous_close:
                self.green_streak += 1
                self.red_streak = 0
            else:
                self.red_streak = 0
                self.green_streak = 0

        self.close = close
        self.sma_ready = self.sma.is_ready
        self.sma_value = float(self.sma.current.value) if self.sma.is_ready else None
        self.bars_seen += 1

    # -- rule helpers -------------------------------------------------------------
    @property
    def cross_ready(self):
        return (self.sma_ready and self.previous_sma_ready
                and self.close is not None and self.previous_close is not None)

    @property
    def close_crossed_above_sma(self):
        """Yesterday close <= yesterday SMA, today close > today SMA."""
        if not self.cross_ready:
            return False
        return (self.previous_close <= self.previous_sma_value) and (self.close > self.sma_value)

    @property
    def close_crossed_below_sma(self):
        """Yesterday close >= yesterday SMA, today close < today SMA."""
        if not self.cross_ready:
            return False
        return (self.previous_close >= self.previous_sma_value) and (self.close < self.sma_value)

    def red_for(self, n):
        """True on any day completing n or more consecutive red days."""
        return self.red_streak >= n

    @property
    def rsi_value(self):
        return float(self.rsi.current.value) if self.rsi.is_ready else None


class StrategyLot(object):
    """A strategy's private lot: it can only ever sell shares it bought itself."""

    def __init__(self, name, symbol):
        self.name = name
        self.symbol = symbol
        self.shares = 0      # filled shares owned by this strategy
        self.pending = 0     # signed quantity of this strategy's unfilled orders

    @property
    def is_empty(self):
        return self.shares == 0

    @property
    def is_busy(self):
        return self.pending != 0

    @property
    def can_buy(self):
        return self.is_empty and not self.is_busy

    @property
    def can_sell(self):
        return (not self.is_empty) and not self.is_busy


class ParallelTwoSlotTemplateAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        self.symbols = []
        self.trackers = {}
        for ticker in TICKERS:
            equity = self.add_equity(ticker, Resolution.DAILY)
            symbol = equity.symbol
            self.symbols.append(symbol)
            self.trackers[symbol] = SymbolTracker(symbol)

        self.spy = self.symbols[TICKERS.index("SPY")]
        self.aapl = self.symbols[TICKERS.index("AAPL")]

        # Slot 1 and Slot 2 of the (ungated) template, each with its own private lot.
        self.lot_a = StrategyLot("Strategy A", self.spy)
