from AlgorithmImports import *

import math
# endregion


# --- Rule parameters ----------------------------------------------------------
# The specification does not state a length for Strategy A's moving average, so the
# conventional 50-day simple moving average of daily closes is used.
SMA_PERIOD = 50

RSI_PERIOD = 14            # Strategy B's RSI length
RSI_SELL_LEVEL = 60.0      # Strategy B sells when RSI closes above this level
RED_DAYS_REQUIRED = 3      # Strategy B buys after this many consecutive red closes
SPY_ALLOCATION = 0.40      # Strategy A invests this fraction of total portfolio value
AAPL_TRADE_CASH = 20000.0  # Strategy B spends this much cash, only if it is available

TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
WARM_UP_BARS = 260         # ~1 trading year, so every indicator is fully formed at the start


class SymbolState:
    """Market state for one ticker, updated continuously from every bar received."""

    def __init__(self, symbol):
        self.symbol = symbol
        self.bars_seen = 0

        self.open = None
        self.close = None
        self.prev_close = None

        # "Red for n consecutive days" is satisfied on any day completing n or more red days.
        self.red_streak = 0

        self.sma = None
        self.sma_value = None
        self.prev_sma_value = None

        self.rsi = None
        self.rsi_value = None

    def attach_sma(self, period):
        self.sma = SimpleMovingAverage(period)

    def attach_rsi(self, period):
        self.rsi = RelativeStrengthIndex(period, MovingAverageType.WILDERS)

    def update(self, bar):
        """Fold today's bar into the running state. Never gated by any template."""
        close = bar.close

        if self.prev_close is not None and close < self.prev_close:
            self.red_streak += 1
        else:
            self.red_streak = 0

        self.open = bar.open
        self.close = close

        if self.sma is not None:
            self.sma.update(bar.end_time, close)
            self.sma_value = self.sma.current.value if self.sma.is_ready else None

        if self.rsi is not None:
            self.rsi.update(bar.end_time, close)
            self.rsi_value = self.rsi.current.value if self.rsi.is_ready else None

        self.bars_seen += 1

    def commit(self):
        """Roll today's values into yesterday's slots, once the bar is fully processed."""
        self.prev_close = self.close
        self.prev_sma_value = self.sma_value

    def close_crossed_above_sma(self):
        if self.prev_close is None or self.prev_sma_value is None or self.sma_value is None:
            return False
        return self.prev_close <= self.prev_sma_value and self.close > self.sma_value

    def close_crossed_below_sma(self):
        if self.prev_close is None or self.prev_sma_value is None or self.sma_value is None:
            return False
        return self.prev_close >= self.prev_sma_value and self.close < self.sma_value


class Lot:
    """A strategy's private inventory: it can only ever sell shares it bought itself."""

    def __init__(self, algorithm, symbol, owner):
        self._algorithm = algorithm
        self.symbol = symbol
        self.owner = owner
        self.quantity = 0

    @property
    def is_empty(self):
        return self.quantity == 0

    def buy(self, quantity, reason):
        quantity = int(quantity)
        if quantity <= 0:
            return
        self._algorithm.place_lot_order(self, quantity, reason)

    def sell(self, quantity, reason):
        quantity = int(min(abs(int(quantity)), self.quantity))
        if quantity <= 0:
            return
        self._algorithm.place_lot_order(self, -quantity, reason)

    def liquidate(self, reason):
        self.sell(self.quantity, reason)


class StrategyA:
    """Slot 1 - SPY, close versus its moving average."""

    name = "Strategy A"

    def __init__(self, algorithm, state, lot):
        self._algorithm = algorithm
        self._state = state
        self.lot = lot

    def evaluate_sell(self):
        if self.lot.is_empty:
            return
        if self._state.close_crossed_below_sma():
            self.lot.liquidate(f"{self.name} sell: SPY close crossed below its {SMA_PERIOD}-day MA")

    def evaluate_buy(self):
        if not self.lot.is_empty:
            return
        if not self._state.close_crossed_above_sma():
            return
        target_value = float(self._algorithm.portfolio.total_portfolio_value) * SPY_ALLOCATION
        shares = int(math.floor(target_value / self._state.close))
        self.lot.buy(shares, f"{self.name} buy: SPY close crossed above its {SMA_PERIOD}-day MA")


class StrategyB:
    """Slot 2 - AAPL, red-day streak in, RSI level out."""

    name = "Strategy B"

    def __init__(self, algorithm, state, lot):
        self._algorithm = algorithm
        self._state = state
        self.lot = lot

    def evaluate_sell(self):
        if self.lot.is_empty:
            return
        if self._state.rsi_value is not None and self._state.rsi_value > RSI_SELL_LEVEL:
            self.lot.liquidate(f"{self.name} sell: AAPL {RSI_PERIOD}-day RSI closed above {RSI_SELL_LEVEL:.0f}")

    def evaluate_buy(self):
        if not self.lot.is_empty:
            return
        if self._state.red_streak < RED_DAYS_REQUIRED:
            return
        # Buy the fixed dollar amount only if that much cash is available, otherwise do nothing.
        if float(self._algorithm.portfolio.cash) < AAPL_TRADE_CASH:
            return
        shares = int(math.floor(AAPL_TRADE_CASH / self._state.close))
        self.lot.buy(shares, f"{self.name} buy: AAPL red {RED_DAYS_REQUIRED} consecutive days")


class ParallelSlotTemplateAlgorithm(QCAlgorithm):
    """
    One template, two slots, no gate. Both slots run independently in parallel and
    each keeps its own private lot. Rules are evaluated once per daily bar, sells
    before buys, and only on days when every subscribed ticker has a bar.
    """

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self._states = {}
        symbols = {}
        for ticker in TICKERS:
            equity = self.add_equity(ticker, Resolution.DAILY)
            equity.set_data_normalization_mode(DataNormalizationMode.ADJUSTED)
            symbols[ticker] = equity.symbol
            self._states[equity.symbol] = SymbolState(equity.symbol)

        self._spy = symbols["SPY"]
        self._aapl = symbols["AAPL"]

        self._states[self._spy].attach_sma(SMA_PERIOD)
        self._states[self._aapl].attach_rsi(RSI_PERIOD)

        self._lot_orders = {}

        self._slots = [
            StrategyA(self, self._states[self._spy], Lot(self, self._spy, StrategyA.name)),
            StrategyB(self, self._states[self._aapl], Lot(self, self._aapl, StrategyB.name)),
        ]

        self.set_warm_up(WARM_UP_BARS, Resolution.DAILY)

    def on_data(self, slice):
        # 1) Market state is always maintained from whatever data arrives.
        updated = []
        for symbol, state in self._states.items():
            bar = self._get_bar(slice, symbol)
            if bar is not None:
                state.update(bar)
                updated.append(state)

        # 2) Rules are evaluated only when today's bar exists for every subscribed ticker.
        if len(updated) == len(self._states) and not self.is_warming_up and self._rules_ready():
            for slot in self._slots:
                slot.evaluate_sell()
            for slot in self._slots:
                slot.evaluate_buy()

        # 3) Today's values become yesterday's values for the tickers that printed a bar.
        for state in updated:
            state.commit()

    def _get_bar(self, slice, symbol):
        if slice is None:
            return None
        bars = slice.bars
        if bars is None or not bars.contains_key(symbol):
            return None
        bar = bars[symbol]
        if bar is None or bar.close <= 0:
            return None
        return bar

    def _rules_ready(self):
        """No trading until every indicator and rolling window used by a rule is fully formed."""
        spy = self._states[self._spy]
        aapl = self._states[self._aapl]
        return (spy.sma_value is not None
                and spy.prev_sma_value is not None
                and spy.prev_close is not None
                and aapl.rsi_value is not None
                and aapl.bars_seen > RED_DAYS_REQUIRED)

    def place_lot_order(self, lot, signed_quantity, reason):
        ticket = self.market_order(lot.symbol, signed_quantity, tag=reason)
        # Track the lot optimistically so a slot cannot re-fire while its order is in flight;
        # anything that never fills is backed out in on_order_event.
        lot.quantity += signed_quantity
        self._lot_orders[ticket.order_id] = [lot, signed_quantity, 0]

    def on_order_event(self, order_event):
        record = self._lot_orders.get(order_event.order_id)
        if record is None:
            return

        lot, ordered, filled = record
        if order_event.fill_quantity != 0:
            filled += int(round(order_event.fill_quantity))
            record[2] = filled

        if order_event.status in (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID):
            unfilled = ordered - filled
            if unfilled != 0:
                lot.quantity -= unfilled
            del self._lot_orders[order_event.order_id]

