class ParallelTwoSlotTemplateAlgorithm(QCAlgorithm):
    """One template, two slots, no gate. Both slots run independently in parallel.

    Slot 1 - Strategy A (SPY): buy when the close crosses above its moving average
             (invest 40% of total portfolio value), sell the whole lot when the
             close crosses back below the moving average.
    Slot 2 - Strategy B (AAPL): buy $20,000 after three consecutive red days if at
             least $20,000 of cash is available, sell the whole lot when the 14-day
             RSI is above 60.
    """

    TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

    # The spec does not fix a length for Strategy A's moving average.
    SMA_PERIOD = 50
    RSI_PERIOD = 14
    RSI_SELL_LEVEL = 60.0      # level test ("closes above"), not a cross
    A_PORTFOLIO_PCT = 0.40
    B_CASH_PER_BUY = 20000.0
    B_RED_DAYS = 3

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        self.symbols = {}
        for ticker in self.TICKERS:
            equity = self.add_equity(ticker, Resolution.DAILY)
            equity.set_data_normalization_mode(DataNormalizationMode.ADJUSTED)
            self.symbols[ticker] = equity.symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Indicators are updated by hand in on_data so that each rule sees today's
        # value on today's bar, and so market state keeps advancing on days when
        # rule evaluation is skipped.
        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(self.RSI_PERIOD, MovingAverageType.WILDERS)

        # Newest value last. A cross test needs today's and yesterday's values;
        # an n-day red streak needs n + 1 closes.
        self.spy_closes = deque(maxlen=2)
        self.spy_sma_values = deque(maxlen=2)
        self.aapl_closes = deque(maxlen=self.B_RED_DAYS + 1)

        # Private lots: a strategy only ever sells shares it bought itself.
        self.lot_a = 0
        self.lot_b = 0

        self.set_warm_up(self.SMA_PERIOD + 10, Resolution.DAILY)

    def on_data(self, data):
        # Market-state quantities are always computed from data, continuously.
        self._update_market_state(data)

        if self.is_warming_up or not self._ready():
            return

        # If today's bar is missing for any subscribed ticker, skip all rules today.
        if not self._all_bars_present(data):
            return

        # Sells before buys, slot 1 before slot 2.
        self._strategy_a_sell()
        self._strategy_b_sell()
        self._strategy_a_buy(data)
        self._strategy_b_buy(data)

    # region market state

    def _update_market_state(self, data):
        if data.bars.contains_key(self.spy):
            bar = data.bars[self.spy]
            self.spy_sma.update(bar.end_time, bar.close)
            self.spy_closes.append(float(bar.close))
            if self.spy_sma.is_ready:
                self.spy_sma_values.append(float(self.spy_sma.current.value))

        if data.bars.contains_key(self.aapl):
            bar = data.bars[self.aapl]
            self.aapl_rsi.update(bar.end_time, bar.close)
            self.aapl_closes.append(float(bar.close))

    def _ready(self):
        return (self.spy_sma.is_ready
                and self.aapl_rsi.is_ready
                and len(self.spy_closes) == self.spy_closes.maxlen
                and len(self.spy_sma_values) == self.spy_sma_values.maxlen
                and len(self.aapl_closes) == self.aapl_closes.maxlen)

    def _all_bars_present(self, data):
        return all(data.bars.contains_key(symbol) for symbol in self.symbols.values())

    # endregion

    # region slot 1 - strategy A (SPY)

    def _strategy_a_buy(self, data):
        if self.lot_a != 0:
            return
        if not self._crossed_above(self.spy_closes, self.spy_sma_values):
            return

        price = float(data.bars[self.spy].close)
        quantity = int((self.A_PORTFOLIO_PCT * float(self.portfolio.total_portfolio_value)) / price)
        if quantity <= 0:
            return
        if self._submit(self.spy, quantity):
            self.lot_a = quantity

    def _strategy_a_sell(self):
        if self.lot_a == 0:
            return
        if not self._crossed_below(self.spy_closes, self.spy_sma_values):
            return
        if self._submit(self.spy, -self.lot_a):
            self.lot_a = 0

    # endregion

    # region slot 2 - strategy B (AAPL)

    def _strategy_b_buy(self, data):
        if self.lot_b != 0:
            return
        if not self._red_streak(self.aapl_closes, self.B_RED_DAYS):
            return
        # Not enough cash: do nothing this bar, the reason may fire again later.
        if float(self.portfolio.cash) < self.B_CASH_PER_BUY:
            return

        price = float(data.bars[self.aapl].close)
        quantity = int(self.B_CASH_PER_BUY / price)  # floor
        if quantity <= 0:
            return
        if self._submit(self.aapl, quantity):
            self.lot_b = quantity

    def _strategy_b_sell(self):
        if self.lot_b == 0:
            return
        if float(self.aapl_rsi.current.value) <= self.RSI_SELL_LEVEL:
            return
        if self._submit(self.aapl, -self.lot_b):
            self.lot_b = 0

    # endregion

    # region helpers

    def _submit(self, symbol, quantity):
        ticket = self.market_order(symbol, quantity)
        return ticket is not None and ticket.status != OrderStatus.INVALID

    @staticmethod
    def _crossed_above(x, y):
        return x[-2] <= y[-2] and x[-1] > y[-1]

    @staticmethod
    def _crossed_below(x, y):
        return x[-2] >= y[-2] and x[-1] < y[-1]

    @staticmethod
    def _red_streak(closes, days):
        last = len(closes)
        return all(closes[i] < closes[i - 1] for i in range(last - days, last))

    # endregion

