# region imports
from AlgorithmImports import *
import math
# endregion


class SymbolState:
    """
    Per-ticker market state.  Updated continuously from every bar that prints,
    independently of whether any rule is allowed to be evaluated that day.
    """

    def __init__(self):
        self.close = None
        self.prev_close = None
        self.red_streak = 0
        self.green_streak = 0

    @property
    def IsReady(self):
        # a streak/direction can only be known once we have a previous close
        return self.prev_close is not None

    def Update(self, bar):
        previous = self.close
        self.prev_close = previous
        self.close = bar.Close

        if previous is None:
            return

        if bar.Close < previous:          # strictly below -> red day
            self.red_streak += 1
            self.green_streak = 0
        elif bar.Close > previous:        # strictly above -> green day
            self.green_streak += 1
            self.red_streak = 0
        else:                             # unchanged -> neither
            self.red_streak = 0
            self.green_streak = 0


class Lot:
    """
    A strategy's private inventory of shares.  A strategy can only ever sell
    shares that this lot bought.  In-flight (pending) quantity counts towards
    the lot so a reason cannot fire twice while an order is still working.
    """

    def __init__(self, algorithm, symbol, owner):
        self.algorithm = algorithm
        self.symbol = symbol
        self.owner = owner
        self.shares = 0
        self.pending = 0

    @property
    def Total(self):
        return self.shares + self.pending

    @property
    def IsOpen(self):
        return self.Total > 0

    def Buy(self, quantity):
        quantity = int(math.floor(quantity))
        if quantity <= 0:
            return
        ticket = self.algorithm.MarketOrder(self.symbol, quantity, False, self.owner + " BUY")
        self.algorithm.RegisterTicket(ticket, self)
        self.pending += quantity

    def Sell(self, quantity):
        quantity = int(min(math.floor(quantity), self.shares))
        if quantity <= 0:
            return
        ticket = self.algorithm.MarketOrder(self.symbol, -quantity, False, self.owner + " SELL")
        self.algorithm.RegisterTicket(ticket, self)
        self.pending -= quantity

    def SellHalf(self):
        if self.shares <= 0:
            return
        # sell the last share when only one remains
        self.Sell(self.shares if self.shares == 1 else math.floor(self.shares / 2.0))

    def Liquidate(self):
        self.Sell(self.shares)

    def OnFill(self, fill_quantity):
        self.shares += int(fill_quantity)
        self.pending -= int(fill_quantity)

    def OnTerminal(self, unfilled_quantity):
        # release the reserved-but-never-filled portion (cancelled / invalid)
        self.pending -= int(unfilled_quantity)


class Strategy:
    """
    One slot of a template.  Sells are evaluated only while the lot is
    non-empty, buys only while the lot is empty, and sells go before buys.
    """

    def __init__(self, algorithm, symbol, name):
        self.algorithm = algorithm
        self.symbol = symbol
        self.name = name
        self.lot = Lot(algorithm, symbol, name)

    def EvaluateSell(self, bars):
        if not self.lot.IsOpen:
            return
        if self.ReasonToSell(bars):
            self.SellDetails(bars)

    def EvaluateBuy(self, bars):
        if self.lot.IsOpen:
            return
        if self.ReasonToBuy(bars):
            self.BuyDetails(bars)

    # ---- overridden by the concrete strategies -------------------------
    def ReasonToSell(self, bars):
        return False

    def SellDetails(self, bars):
        pass

    def ReasonToBuy(self, bars):
        return False

    def BuyDetails(self, bars):
        pass


class StrategyA(Strategy):
    """
    Slot 1 - trades SPY.
      Buy  : SPY close crosses above its 100-day SMA -> 40% of portfolio value.
      Sell : SPY close crosses below its 100-day SMA -> liquidate the lot.
    """

    TARGET_WEIGHT = 0.40

    def ReasonToSell(self, bars):
        return self.algorithm.spy_cross_below

    def SellDetails(self, bars):
        self.lot.Liquidate()

    def ReasonToBuy(self, bars):
