from AlgorithmImports import *
# endregion


class SymbolState:
    """
    Continuously-maintained market state for one subscribed ticker.

    Everything in here is computed from data on every bar the ticker prints,
    independently of any template gate or strategy position.
    """

    def __init__(self, symbol):
        self.symbol = symbol

        # Indicators are updated manually so that the ordering with respect to
        # rule evaluation (indicators first, then rules) is fully deterministic.
        self._sma_100 = SimpleMovingAverage(100)
        self._rsi_14 = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.close = None
        self.prev_close = None

        self.sma_100 = None
        self.prev_sma_100 = None
        self.sma_100_ready = False
        self.prev_sma_100_ready = False

        self.rsi_14 = None
        self.prev_rsi_14 = None
        self.rsi_14_ready = False
        self.prev_rsi_14_ready = False

        self.red_streak = 0
        self.green_streak = 0

    def update(self, bar):
        # Roll today's values into yesterday's slots before recomputing.
        self.prev_close = self.close
        self.prev_sma_100 = self.sma_100
        self.prev_sma_100_ready = self.sma_100_ready
        self.prev_rsi_14 = self.rsi_14
        self.prev_rsi_14_ready = self.rsi_14_ready

        close = float(bar.close)
        end_time = bar.end_time

        self._sma_100.update(end_time, close)
        self.sma_100_ready = bool(self._sma_100.is_ready)
        self.sma_100 = float(self._sma_100.current.value) if self.sma_100_ready else None

        self._rsi_14.update(end_time, close)
        self.rsi_14_ready = bool(self._rsi_14.is_ready)
        self.rsi_14 = float(self._rsi_14.current.value) if self.rsi_14_ready else None

        # Red / green streaks: strictly below / strictly above the previous close.
        if self.prev_close is not None:
            if close < self.prev_close:
                self.red_streak += 1
                self.green_streak = 0
            elif close > self.prev_close:
                self.green_streak += 1
                self.red_streak = 0
            else:
                self.red_streak = 0
                self.green_streak = 0

        self.close = close

    def close_crossed_above_sma_100(self):
        """Yesterday close <= yesterday SMA and today close > today SMA."""
        if not (self.sma_100_ready and self.prev_sma_100_ready):
            return False
        if self.close is None or self.prev_close is None:
            return False
        return self.prev_close <= self.prev_sma_100 and self.close > self.sma_100

    def close_crossed_below_sma_100(self):
        """Yesterday close >= yesterday SMA and today close < today SMA."""
        if not (self.sma_100_ready and self.prev_sma_100_ready):
            return False
        if self.close is None or self.prev_close is None:
            return False
        return self.prev_close >= self.prev_sma_100 and self.close < self.sma_100


class StrategyLot:
    """
    A private lot of shares belonging to exactly one strategy.  A strategy only
    ever sells shares that its own lot bought.
    """

    def __init__(self, algorithm, symbol, owner_name):
        self.algorithm = algorithm
        self.symbol = symbol
        self.owner_name = owner_name
        self.shares = 0
        self._pending = {}

    @property
    def is_open(self):
        return self.shares > 0

    @property
    def is_empty(self):
        return self.shares <= 0

    def buy(self, quantity, tag):
        quantity = int(quantity)
        if quantity <= 0:
            return
        ticket = self.algorithm.market_order(
            self.symbol, quantity, tag=f"{self.owner_name}: {tag}")
        if ticket is None or ticket.status in (OrderStatus.INVALID, OrderStatus.CANCELED):
            return
        self.shares += quantity
        if ticket.status != OrderStatus.FILLED:
            self._pending[ticket.order_id] = quantity

    def sell(self, quantity, tag):
        quantity = int(min(int(quantity), self.shares))
        if quantity <= 0:
            return
        ticket = self.algorithm.market_order(
            self.symbol, -quantity, tag=f"{self.owner_name}: {tag}")
        if ticket is None or ticket.status in (OrderStatus.INVALID, OrderStatus.CANCELED):
            return
        self.shares -= quantity
        if ticket.status != OrderStatus.FILLED:
            self._pending[ticket.order_id] = -quantity

    def liquidate(self, tag):
        self.sell(self.shares, tag)

    def sell_half(self, tag):
        if self.shares <= 1:
            self.sell(self.shares, tag)
        else:
            self.sell(self.shares // 2, tag)

    def on_order_event(self, order_event):
        delta = self._pending.get(order_event.order_id, None)
        if delta is None:
            return
        if order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
            self.shares -= delta
            del self._pending[order_event.order_id]
        elif order_event.status == OrderStatus.FILLED:
            del self._pending[order_event.order_id]


class StrategyA:
    """
    Slot 1 - trades SPY.
      Buy  : SPY close crosses above its 100-day SMA -> invest 40% of TPV.
      Sell : SPY close crosses below its 100-day SMA -> liquidate the lot.
    """

    NAME = "Strategy A"

    def __init__(self, algorithm, symbol):
        self.algorithm = algorithm
        self.symbol = symbol
        self.lot = StrategyLot(algorithm, symbol, self.NAME)

    def evaluate_sell(self, states):
        if self.lot.is_empty:
            return
        state = states[self.symbol]
        if state.close_crossed_below_sma_100():
            self.lot.liquidate("SPY close crossed below 100-day SMA")

    def evaluate_buy(self, states):
        if self.lot.is_open:
            return
        state = states[self.symbol]
        if state.close_crossed_above_sma_100():
            target_value = 0.40 * float(self.algorithm.portfolio.total_portfolio_value)
            quantity = int(target_value / state.close)
            self.lot.buy(quantity, "SPY close crossed above 100-day SMA - invest 40%")

    def liquidate_all(self, reason):
        self.lot.liquidate(reason)

    def reset_state(self):
        pass


class StrategyB:
    """
    Slot 2 - trades AAPL.
      Buy  : AAPL red for 3 consecutive days -> buy $20,000 if >= $20,000 cash.
      Sell : AAPL 14-day RSI closes above 60 -> liquidate the lot.
    """

    NAME = "Strategy B"
    CASH_REQUIRED = 20000.0

    def __init__(self, algorithm, symbol):
        self.algorithm = algorithm
        self.symbol = symbol
        self.lot = StrategyLot(algorithm, symbol, self.NAME)

    def evaluate_sell(self, states):
