                quantity = int(self.CASH_REQUIRED / state.close)
                self.lot.buy(quantity, "AAPL red 3 days - buy $20,000")
            # Otherwise do nothing this bar; the reason may fire again later.

    def liquidate_all(self, reason):
        self.lot.liquidate(reason)

    def reset_state(self):
        pass


class ParallelTemplate:
    """
    Ungated template holding independent slots that run in parallel.
    On every bar, all sells are evaluated before any buys.
    """

    def __init__(self, name, slots):
        self.name = name
        self.slots = slots

    def on_bar(self, states):
        for slot in self.slots:
            slot.evaluate_sell(states)
        for slot in self.slots:
            slot.evaluate_buy(states)

    def on_order_event(self, order_event):
        for slot in self.slots:
            slot.lot.on_order_event(order_event)


class TwoSlotParallelTemplateAlgorithm(QCAlgorithm):

    TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        self.symbols = []
        self.states = {}
        self.ticker_symbols = {}
        for ticker in self.TICKERS:
            equity = self.add_equity(ticker, Resolution.DAILY)
            symbol = equity.symbol
            self.symbols.append(symbol)
            self.ticker_symbols[ticker] = symbol
            self.states[symbol] = SymbolState(symbol)

        self.template = ParallelTemplate(
            "Root",
            [
                StrategyA(self, self.ticker_symbols["SPY"]),
                StrategyB(self, self.ticker_symbols["AAPL"]),
            ],
        )

    def on_data(self, data: Slice):
        # Market state is always computed from data, continuously.
        present = 0
        for symbol in self.symbols:
            bar = data.bars[symbol] if data.bars.contains_key(symbol) else None
            if bar is None or bar.close <= 0:
                continue
