        prev_sma = self.prev_spy_sma

        a_ready = self.spy_sma.is_ready and prev_sma is not None and prev_spy_close is not None
        cross_above = a_ready and prev_spy_close <= prev_sma and spy_close > sma
        cross_below = a_ready and prev_spy_close >= prev_sma and spy_close < sma

        aapl_close = bars[self.aapl].close
        b_ready = self.aapl_rsi.is_ready
        rsi_above_60 = b_ready and self.aapl_rsi.current.value > self.RSI_SELL_LEVEL
        three_red_days = self.red_streak[self.aapl] >= self.B_RED_DAYS

        # ---- sells first, in slot order ----
        if self.lot_a.is_open and cross_below:
            self.submit(self.lot_a, -self.lot_a.net, "A: SPY close crossed below SMA100")

        if self.lot_b.is_open and rsi_above_60:
            self.submit(self.lot_b, -self.lot_b.net, "B: AAPL RSI14 closed above 60")

        # ---- then buys, in slot order ----
        if self.lot_a.is_empty and cross_above:
            target_value = self.A_ALLOCATION * self.portfolio.total_portfolio_value
            quantity = int(math.floor(target_value / spy_close))
            if quantity > 0:
