                if quantity > 0:
                    self.submit(self.lot_b, quantity, "B: AAPL red 3 consecutive days")

    # ---------------------------------------------------------------- orders

    def submit(self, lot, quantity, tag):
        if quantity == 0:
            return
        ticket = self.market_order(lot.symbol, quantity, tag=tag)
        if ticket is None:
            return
        self.order_owner[ticket.order_id] = lot
        lot.on_submit(quantity)

