class SymbolState:
    """Continuously-maintained market state for one subscribed ticker.

    These quantities are updated from data on every bar the ticker prints,
    independently of whether the strategy rules are allowed to run that day.
    """

    def __init__(self):
        self.close = None          # today's close
        self.prev_close = None     # previous bar's close
        self.open = None           # today's open
        self.red_streak = 0        # consecutive red days ending today
        self.green_streak = 0      # consecutive green days ending today
        self.bars_seen = 0

    def update(self, bar):
        self.prev_close = self.close
        self.close = bar.Close
        self.open = bar.Open
        if self.prev_close is not None:
            if self.close < self.prev_close:       # red day (strictly below)
                self.red_streak += 1
                self.green_streak = 0
            elif self.close > self.prev_close:     # green day (strictly above)
                self.green_streak += 1
                self.red_streak = 0
            else:                                  # unchanged: neither
                self.red_streak = 0
                self.green_streak = 0
        self.bars_seen += 1


class StrategyLot:
    """A strategy's private lot: it only ever sells shares it bought itself."""

    def __init__(self, name, symbol):
        self.name = name
        self.symbol = symbol
        self.shares = 0      # shares currently owned by this strategy
