# region imports
from AlgorithmImports import *
from collections import deque
# endregion


class Lot:
    """
    A private lot of shares owned by exactly one strategy.

    A strategy only ever sells shares that it bought itself, so every position is
    tracked here rather than being read back out of the shared portfolio.
    """

    def __init__(self, algorithm, name, symbol):
        self._algorithm = algorithm
        self.name = name
        self.symbol = symbol
        self.shares = 0          # shares currently held by this lot
        self.pending = 0         # orders submitted by this lot that are not terminal yet

    @property
    def is_empty(self):
        return self.shares == 0

    @property
    def is_quiet(self):
        """True when the lot has no in-flight order, i.e. its state is trustworthy."""
        return self.pending == 0

    def buy(self, quantity, reason):
        quantity = int(quantity)
        if quantity <= 0:
            return
        self._submit(quantity, reason)

    def liquidate(self, reason):
        if self.shares <= 0:
            return
        self._submit(-self.shares, reason)

    def _submit(self, quantity, reason):
        ticket = self._algorithm.MarketOrder(
            self.symbol, quantity, False, "{0}: {1}".format(self.name, reason))
        if ticket is None or ticket.Status == OrderStatus.Invalid:
            return
        self.pending += 1
        self._algorithm.order_lots[ticket.OrderId] = self

    def on_order_event(self, order_event):
        if order_event.Status in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
            self.shares += int(order_event.FillQuantity)
            if self.shares < 0:
                self.shares = 0
        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled,
                                  OrderStatus.Invalid, OrderStatus.CancelPending):
            if order_event.Status != OrderStatus.CancelPending:
                self.pending = max(0, self.pending - 1)


class TwoSlotParallelTemplate(QCAlgorithm):
    """
    One template with two slots and no gate; both slots run independently, in parallel.

      Slot 1 - Strategy A (SPY)
          buy : SPY close crosses above its 100-day moving average
                -> invest 40% of total portfolio value
          sell: SPY close crosses below its 100-day moving average
                -> liquidate Strategy A's lot

      Slot 2 - Strategy B (AAPL)
          buy : AAPL red for 3 consecutive days
                -> buy $20,000 of AAPL if at least $20,000 cash is available
          sell: AAPL 14-day RSI closes above 60
                -> liquidate Strategy B's lot
    """

    TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = []
        for ticker in self.TICKERS:
            self.symbols.append(self.AddEquity(ticker, Resolution.Daily).Symbol)
        self.spy = self.symbols[0]
        self.aapl = self.symbols[1]

        # ---- market state, recomputed from data on every bar that arrives ----------
        self.prev_close = {symbol: None for symbol in self.symbols}
        self.red_streak = {symbol: 0 for symbol in self.symbols}

        # Indicators are updated by hand so their ordering relative to rule
        # evaluation (today's value vs. yesterday's value) is explicit.
        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        # last two (close, sma value, sma ready) snapshots for SPY -> cross detection
        self.spy_snapshots = deque(maxlen=2)

        # ---- the template's two slots ---------------------------------------------
        self.lot_a = Lot(self, "Strategy A", self.spy)
        self.lot_b = Lot(self, "Strategy B", self.aapl)
        self.order_lots = {}

    # ------------------------------------------------------------------ data --------
    def OnData(self, data):
        bars = {}
        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]
                if bar is not None and bar.Close > 0:
                    bars[symbol] = bar

        # Market-state quantities (streaks, indicators) are always computed from
        # data, continuously, whether or not any rule is allowed to be evaluated.
        self.UpdateMarketState(bars)

        # If today's bar is missing for ANY subscribed ticker, skip all rules today.
        if len(bars) != len(self.symbols):
            return

        # On any bar, sells are evaluated before buys.
        self.StrategyASell()
        self.StrategyBSell()
        self.StrategyABuy(bars[self.spy])
        self.StrategyBBuy(bars[self.aapl])

    def UpdateMarketState(self, bars):
        for symbol, bar in bars.items():
            previous = self.prev_close[symbol]
            if previous is not None:
                # red day = close strictly below the previous day's close
                if bar.Close < previous:
                    self.red_streak[symbol] += 1
                else:
                    self.red_streak[symbol] = 0
            self.prev_close[symbol] = bar.Close

        spy_bar = bars.get(self.spy)
        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_snapshots.append(
                (float(spy_bar.Close), float(self.spy_sma.Current.Value), self.spy_sma.IsReady))

        aapl_bar = bars.get(self.aapl)
        if aapl_bar is not None:
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

    # ------------------------------------------------------- slot 1: strategy A -----
    def StrategyAReady(self):
        # Both today's and yesterday's SMA values must be fully formed to call a cross.
        return len(self.spy_snapshots) == 2 and self.spy_snapshots[0][2] and self.spy_snapshots[1][2]

    def SpyCrossedAbove(self):
        if not self.StrategyAReady():
            return False
        (y_close, y_sma, _), (t_close, t_sma, _) = self.spy_snapshots[0], self.spy_snapshots[1]
        return y_close <= y_sma and t_close > t_sma

    def SpyCrossedBelow(self):
        if not self.StrategyAReady():
            return False
        (y_close, y_sma, _), (t_close, t_sma, _) = self.spy_snapshots[0], self.spy_snapshots[1]
        return y_close >= y_sma and t_close < t_sma

    def StrategyASell(self):
        if not self.lot_a.is_quiet or self.lot_a.is_empty:
            return
        if self.SpyCrossedBelow():
            self.lot_a.liquidate("close crossed below the 100-day SMA")

    def StrategyABuy(self, spy_bar):
        if not self.lot_a.is_quiet or not self.lot_a.is_empty:
            return
        if not self.SpyCrossedAbove():
            return
        target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
        quantity = int(target_value / float(spy_bar.Close))
        self.lot_a.buy(quantity, "close crossed above the 100-day SMA")

    # ------------------------------------------------------- slot 2: strategy B -----
    def StrategyBReady(self):
        # The 14-day RSI used by this strategy's sell rule must be fully formed.
        return self.aapl_rsi.IsReady

    def StrategyBSell(self):
        if not self.lot_b.is_quiet or self.lot_b.is_empty or not self.StrategyBReady():
            return
        if float(self.aapl_rsi.Current.Value) > 60.0:
            self.lot_b.liquidate("14-day RSI closed above 60")

    def StrategyBBuy(self, aapl_bar):
        if not self.lot_b.is_quiet or not self.lot_b.is_empty or not self.StrategyBReady():
            return
        if self.red_streak[self.aapl] < 3:
            return
        budget = 20000.0
        if float(self.Portfolio.Cash) < budget:
            return          # not enough cash available: do nothing this bar
        quantity = int(budget / float(aapl_bar.Close))
        self.lot_b.buy(quantity, "3 consecutive red days")

    # ----------------------------------------------------------------- orders -------
    def OnOrderEvent(self, orderEvent):
        lot = self.order_lots.get(orderEvent.OrderId)
        if lot is None:
            return
        lot.on_order_event(orderEvent)
        if orderEvent.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            self.order_lots.pop(orderEvent.OrderId, None)

